/**
 * Unit tests for SubLine#intersection.
 */
public class SubLine_intersection_TriageGen5Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testIntersection_OneOutside_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (10,10)
        // Line 2: (11,0) to (20,10) -> intersection of infinite lines is at (5.5, 5.5)
        // But Line 2's segment is far away.
        SubLine line1 = new SubLine(new Vector2D(0, 0), new Vector2D(10, 10));
        SubLine line2 = new SubLine(new Vector2D(11, 0), new Vector2D(20, 10));

        // Infinite lines intersect at (5.5, 5.5). 
        // (5.5, 5.5) is INSIDE line1, but OUTSIDE line2.
        Vector2D result = line1.intersection(line2, true);

        assertNull(result);
    }




}

